/* Heavy numeric tables extracted from app runtime for maintainability. */
(function(global){
    "use strict";

    function unb64(s) {
        var b = atob(s), n = b.length, u = new Uint8Array(n);
        for (var i = 0; i < n; i++) u[i] = b.charCodeAt(i);
        return u;
    }

var Wt = new Float32Array(unb64("").buffer);
    // 31*15*21
    var SCt = new Float32Array(unb64("").buffer);
    // 21*100
    var CEIL = unb64("");
    // bodies*21
    var CON = unb64("");
    // [attr 21][hb 31][k 6] of {target, maxGap}
    var LERP = new Float32Array(unb64("").buffer);

    global.GBL_BUILD_TABLES = {
        Wt: Wt,
        SCt: SCt,
        CEIL: CEIL,
        CON: CON,
        LERP: LERP
    };
})(typeof window !== "undefined" ? window : globalThis);
